args.command:
python - <<'PY'
from pathlib import Path
for p in Path('.').rglob('*'):
    if p.is_file() and '.git' not in p.parts and 'node_modules' not in p.parts:
        try: s=p.read_text()
        except: continue
        if 'webhook' in s.lower() or ('dispatch' in s.lower() and 'memo' in s.lower()):
            for i,line in enumerate(s.splitlines(),1):
                if 'webhook' in line.lower() or ('dispatch' in line.lower() and 'memo' in line.lower()): print(f'{p}:{i}:{line}')
PY

